import json, re
B = '/home/claude/teg-tutorial/mocktest/banks/'
def CL(text, blanks, ex='Collocation and grammar clues around each gap.'):
    # blanks: list of (answer, [distractors...]) - options = answer + distractors (shuffled at render by order of list)
    bl = {}
    for i, (a, ds) in enumerate(blanks):
        opts = [a] + ds
        opts = opts[i % len(opts):] + opts[:i % len(opts)]  # vary key position
        bl[str(i)] = {'options': opts, 'answer': a}
    return {'type': 'cloze', 'text': text, 'blanks': bl, 'explain': ex}
def RW(n, text, blanks): return {'id': f'RW{n}', 'title': 'R&W Fill in the blanks', 'instructions': 'There are some words missing in the following text. Choose the best option for each gap.', 'questions': [CL(text, blanks)]}
def RF(n, text, blanks):
    words = [a for a, _ in blanks]; extra = sum((ds[:1] for _, ds in blanks), [])
    box = words + extra
    bl = {str(i): {'options': sorted(box), 'answer': a} for i, (a, _) in enumerate(blanks)}
    return {'id': f'RF{n}', 'title': 'Reading: Fill in the blanks', 'instructions': 'In the text below some words are missing. Choose the correct word from the box for each gap. (In the real test you drag words from a box.)', 'questions': [{'type': 'cloze', 'text': text, 'blanks': bl, 'explain': 'Grammar (part of speech) and meaning decide each gap.'}]}
def MM(n, passage, q, opts, ans): return {'id': f'MM{n}', 'title': 'MC multiple answers', 'instructions': 'Read the text and answer the question by selecting all the correct responses. More than one response is correct. Incorrect selections lose marks.', 'passage': f'<p>{passage}</p>', 'questions': [{'type': 'multi', 'prompt': q, 'options': opts, 'answer': ans, 'choose': len(ans), 'negative': True, 'explain': 'Partial credit: +1 for each correct option, -1 for each incorrect option (minimum 0).'}]}
def MS(n, passage, q, opts, ex): return {'id': f'MS{n}', 'title': 'MC single answer', 'instructions': 'Read the text and answer the multiple-choice question by selecting the correct response. Only one response is correct.', 'passage': f'<p>{passage}</p>', 'questions': [{'type': 'mcq', 'prompt': q, 'options': opts, 'answer': 0, 'explain': ex}]}
def RO(n, items): return {'id': f'RO{n}', 'title': 'Re-order paragraphs', 'instructions': 'The text boxes below have been placed in a random order. Restore the original order using the arrows.', 'questions': [{'type': 'order', 'items': items, 'answer': list(range(len(items))), 'explain': 'One point for each correctly ordered adjacent pair. Look for topic sentences, pronouns and linking words.'}]}
CKRA = ['Clear pronunciation', 'Smooth, natural pace without long pauses', 'All words read']
def RA(n, t): return {'id': f'RA{n}', 'title': 'Read aloud', 'instructions': 'Look at the text. You have 30-35 seconds to prepare and about 40 seconds to read aloud.', 'questions': [{'type': 'speak', 'prompt': t, 'prep': 35, 'speak': 40, 'checklist': CKRA}]}
def PI(n, t): return {'id': f'PI{n}', 'title': 'Personal introduction (not scored)', 'instructions': 'Introduce yourself. You have 25 seconds to prepare and 30 seconds to speak. This part is not scored; in the real test it is sent to institutions with your score report.', 'questions': [{'type': 'speak', 'prompt': t, 'prep': 25, 'speak': 30, 'kind': 'pi', 'checklist': ['Name and background', 'Study plans', 'Clear, confident voice']}]}
def tbl(head, rows): return '<table class="data"><tr>' + ''.join(f'<th>{h}</th>' for h in head) + '</tr>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in r) + '</tr>' for r in rows) + '</table>'
def DI(n, what, table, model): return {'id': f'DI{n}', 'title': 'Describe image', 'instructions': 'Look at the table. You have 25 seconds to prepare and 40 seconds to describe it.', 'questions': [{'type': 'speak', 'prompt': f'Describe the {what}.' + table, 'prep': 25, 'speak': 40, 'checklist': ['Overview of the main trend', '2-3 key figures or comparisons', 'Conclusion or implication'], 'model': model}]}
def WT(n, passage, model): return {'id': f'WT{n}', 'title': 'Summarize written text', 'instructions': 'Read the passage and summarise it in ONE sentence of 5-75 words. You have 10 minutes.', 'passage': f'<p>{passage}</p>', 'item_minutes': 10, 'questions': [{'type': 'essay', 'min_words': 5, 'prompt': 'Write one sentence (5-75 words).', 'checklist': ['One sentence only', 'Main idea + key contrast', '5-75 words'], 'model': model}]}
def ES(n, q): return {'id': f'ES{n}', 'title': 'Write essay', 'instructions': 'You have 20 minutes to write a 200-300 word argumentative essay.', 'item_minutes': 20, 'questions': [{'type': 'essay', 'min_words': 200, 'prompt': q, 'checklist': ['200-300 words', 'Clear position', 'Two supported main points', 'Logical paragraphs and linking words', 'Accurate grammar and spelling'], 'model': 'Model structure: introduction with position; two body paragraphs each with a reason and example; short conclusion restating the position.'}]}

